function glyphOrder(words) {
  const before = [];
  for (let x = 0; x < words.length; x++)
    for (let y = x + 1; y < words.length; y++) {
      const a = words[x], b = words[y];
      let i = 0;
      while (i < a.length && i < b.length && a[i] === b[i]) i++;
      if (i === a.length || i === b.length) { if (a.length > b.length) return ''; continue; }
      before.push([a[i], b[i]]);
    }
  let remaining = [...new Set(words.join(''))];
  let order = '';
  while (remaining.length) {
    const free = remaining.filter((g) => !before.some(([p, q]) => q === g && remaining.includes(p))).sort();
    if (!free.length) return '';
    order += free[0];
    remaining = remaining.filter((g) => g !== free[0]);
  }
  return order;
}

function glyphOrder(words) {
  const glyphs = [...new Set(words.join(''))];
  const after = new Map(glyphs.map((g) => [g, new Set()]));
  const indegree = new Map(glyphs.map((g) => [g, 0]));
  for (let w = 0; w + 1 < words.length; w++) {
    const a = words[w], b = words[w + 1];
    let i = 0;
    while (i < a.length && i < b.length && a[i] === b[i]) i++;
    if (i === a.length || i === b.length) {
      if (a.length > b.length) return '';
      continue;
    }
    if (!after.get(a[i]).has(b[i])) {
      after.get(a[i]).add(b[i]);
      indegree.set(b[i], indegree.get(b[i]) + 1);
    }
  }
  const ready = glyphs.filter((g) => indegree.get(g) === 0).sort();
  let order = '';
  while (ready.length) {
    const g = ready.shift();
    order += g;
    for (const next of after.get(g)) {
      indegree.set(next, indegree.get(next) - 1);
      if (indegree.get(next) === 0) { ready.push(next); ready.sort(); }
    }
  }
  return order.length === glyphs.length ? order : '';
}
